import { ciTheme, ciThemeCss, parseHex, toHex } from '@/lib/ci-theme';
import { chartThemeCss } from '@/lib/chart-palette';

/** Brand colors (CI): [primary, secondary, accent]. Server-safe copy of ciStyleCss(): the kit's ci-store.ts is a client module (it imports a React hook) and cannot be imported by the root layout. */
const COLORS: string[] = {{COLORS}};
const valid = (s?: string) => !!s && parseHex(s) !== null;
const norm = (s: string) => toHex(parseHex(s)!);

function brandCss(): string {
  if (!valid(COLORS[0])) return '';
  const [primary, secondary, decor] = COLORS.slice(0, 3).map((c) => (valid(c) ? norm(c) : undefined));
  const theme = ciTheme({ primary: primary!, secondary, decor, harmonize: true });
  return `${ciThemeCss(theme)}\n${chartThemeCss({ primary: primary!, secondary: theme.info.secondary, decor: theme.info.decor })}`;
}

export const BRAND_CSS = brandCss();
